local Furrier = {}
local PRODUCTS = {
    rabbit_fur = { name = "Kunčje krzno", peltCost = 2, saltCost = 1, time = 2, cost = 22, warmth = 30, happiness = 1, description = "Kunčje krzno za kape in obrobe." },
    fox_fur = { name = "Lisica krzno", peltCost = 3, saltCost = 1, alumCost = 1, time = 4, cost = 60, warmth = 45, happiness = 2, prestige = 1, description = "Lisičje krzno za plašče." },
    marten_fur = { name = "Kuna krzno", peltCost = 3, saltCost = 1, alumCost = 1, oilCost = 1, time = 6, cost = 140, warmth = 60, happiness = 3, prestige = 3, description = "Kunčje krzno za plemiče." },
    sable_fur = { name = "Soboljevo krzno", peltCost = 4, saltCost = 1, alumCost = 1, oilCost = 1, time = 8, cost = 320, warmth = 75, happiness = 4, prestige = 7, description = "Soboljevo krzno za visoke plemiče." },
    silver_lined_fur = { name = "Srebrno podloženo krzno", peltCost = 5, silverCost = 1, saltCost = 1, alumCost = 1, oilCost = 1, time = 11, cost = 680, warmth = 88, happiness = 6, prestige = 13, description = "Krzno s srebrno podlogo za kraljevske plašče." },
    royal_ermine_fur = { name = "Kraljevski hermelin krzno", peltCost = 8, goldCost = 1, silverCost = 1, jewelCost = 1, saltCost = 2, alumCost = 2, oilCost = 1, time = 16, cost = 1800, warmth = 100, happiness = 14, prestige = 38, description = "Veliki kraljevski hermelin z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Krznavarska delavnica", cost = { gold = 320, wood = 130, stone = 200 }, upkeep = 8, qualityBonus = 5 },
    furriers_yard = { name = "Krznavarna", cost = { gold = 1000, wood = 250, stone = 400, pelt = 10 }, upkeep = 25, qualityBonus = 18 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 2400, wood = 350, stone = 700, silver = 30, salt = 10 }, upkeep = 60, qualityBonus = 30 },
    royal_furrier_atelier = { name = "Kraljevski atelje krzna", cost = { gold = 9500, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 40 },
}
Furrier.peltStock = 22; Furrier.saltStock = 14; Furrier.alumStock = 14; Furrier.oilStock = 12; Furrier.silverStock = 8; Furrier.goldStock = 6; Furrier.jewelStock = 6
Furrier.productStock = {}; Furrier.buildings = {}; Furrier.maker = nil; Furrier.activeMaking = {}; Furrier.totalProducts = 0; Furrier.dayTimer = 0
function Furrier.init() Furrier.peltStock=22; Furrier.saltStock=14; Furrier.alumStock=14; Furrier.oilStock=12; Furrier.silverStock=8; Furrier.goldStock=6; Furrier.jewelStock=6; Furrier.productStock={}; Furrier.buildings={}; Furrier.maker=nil; Furrier.activeMaking={}; Furrier.totalProducts=0; Furrier.dayTimer=0; print("[Furrier] Royal Furrier System initialized (6 products, 4 buildings)") end
function Furrier.hireMaker(n,s) s=s or math.random(50,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Furrier.maker={name=n or ("Krznavar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krznavar najet: %s (spretnost: %d)",Furrier.maker.name,s),"success") end; return true end
function Furrier.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Furrier.build(id) local ok,e=Furrier.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Furrier.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Furrier.getQualityBonus() local b=0; for _,bd in ipairs(Furrier.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Furrier.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.peltCost and Furrier.peltStock<(d.peltCost or 0) then return false,"Premalo kož" end; if d.saltCost and Furrier.saltStock<(d.saltCost or 0) then return false,"Premalo soli" end; if d.alumCost and Furrier.alumStock<(d.alumCost or 0) then return false,"Premalo aluna" end; if d.oilCost and Furrier.oilStock<(d.oilCost or 0) then return false,"Premalo olja" end; if d.silverCost and Furrier.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and Furrier.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and Furrier.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #Furrier.buildings==0 then return false,"Potrebna delavnica" end; if not Furrier.maker then return false,"Potreben krznavar" end; return true end
function Furrier.make(pt,qty) qty=qty or 5; local ok,e=Furrier.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.peltCost then Furrier.peltStock=Furrier.peltStock-d.peltCost*qty end; if d.saltCost then Furrier.saltStock=Furrier.saltStock-d.saltCost*qty end; if d.alumCost then Furrier.alumStock=Furrier.alumStock-d.alumCost*qty end; if d.oilCost then Furrier.oilStock=Furrier.oilStock-d.oilCost*qty end; if d.silverCost then Furrier.silverStock=Furrier.silverStock-d.silverCost*qty end; if d.goldCost then Furrier.goldStock=Furrier.goldStock-d.goldCost*qty end; if d.jewelCost then Furrier.jewelStock=Furrier.jewelStock-d.jewelCost*qty end; local t=d.time; if Furrier.maker then t=math.max(1,t-math.floor(Furrier.maker.skill/12)) end; table.insert(Furrier.activeMaking,{id="fur_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,warmth=d.warmth or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function Furrier.completeMaking(m) local q=1.0+(Furrier.getQualityBonus()/100); if Furrier.maker then q=q+(Furrier.maker.skill/180) end; q=math.min(2.0,q); Furrier.productStock[m.productType]=(Furrier.productStock[m.productType] or 0)+m.quantity; Furrier.totalProducts=Furrier.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Furrier.maker then Furrier.maker.itemsMade=Furrier.maker.itemsMade+m.quantity; if math.random()<0.20 then Furrier.maker.skill=math.min(100,Furrier.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krzno izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fur.completed",{productName=m.productName,warmth=m.warmth,happiness=m.happiness}) end end
function Furrier.update(dt) if not _G.state then return end; Furrier.dayTimer=Furrier.dayTimer+dt; if Furrier.dayTimer>=30 then Furrier.dayTimer=0; for i=#Furrier.activeMaking,1,-1 do local m=Furrier.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Furrier.completeMaking(m); table.remove(Furrier.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Furrier.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Furrier.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Furrier.getStats() return {peltStock=Furrier.peltStock,saltStock=Furrier.saltStock,alumStock=Furrier.alumStock,oilStock=Furrier.oilStock,silverStock=Furrier.silverStock,goldStock=Furrier.goldStock,jewelStock=Furrier.jewelStock,productStock=Furrier.productStock,numBuildings=#Furrier.buildings,hasMaker=Furrier.maker~=nil,makerName=Furrier.maker and Furrier.maker.name or "—",makerSkill=Furrier.maker and Furrier.maker.skill or 0,activeMaking=#Furrier.activeMaking,totalProducts=Furrier.totalProducts} end
return Furrier
